check.pseudocode:
for path in ["provider/openai", "provider/openairesponses", "provider/google", "provider/ollama", "plugins", "skills", "_skills/code-review", "cmd/validate-plugins", "session", "subagent", "difftest", "imagex", "compaction", "middleware", "stop"]:
    assert !fileExists(path)
for path in ["provider/credentials.go", "provider/credentials_test.go", "provider/salvage.go", "provider/salvage_test.go", "provider/repair.go", "provider/repair_test.go", "provider/asymmetry_test.go", "provider/conformance_test.go", "provider/fuzz_test.go"]:
    assert !fileExists(path)

for path in ["provider/anthropic/anthropic.go", "provider/faux/faux.go"]:
    assert fileExists(path)
for ex in ["examples/agentdemo", "examples/codingagent", "examples/customtools", "examples/codemode", "examples/mcp"]:
    assert fileExists(ex)
for ex in ["examples/branching", "examples/chat", "examples/cleaner", "examples/codesearch", "examples/compaction", "examples/deferred", "examples/delegation", "examples/flatline", "examples/images", "examples/interactive", "examples/mcpserver", "examples/middleware", "examples/observability", "examples/plugins", "examples/session", "examples/skills", "examples/streaming", "examples/testing", "examples/tools", "examples/triage"]:
    assert !fileExists(ex)

approved := map[string]bool{
    "read_file": true, "write_file": true, "edit_file": true,
    "list_files": true, "find_files": true, "search_files": true,
    "file_outline": true, "find_symbol": true, "find_references": true,
    "execute": true, "run_command": true,
}
allTools, err := tools.All(tools.Options{})
for _, t := range allTools {
    assert approved[t.Name]
}

agent := newTestAgent(t)
caller := newNestedCaller(agent, "call_parent_999")
res := caller.Call(ctx, "read_file", json.RawMessage(`{"path":"test.txt"}`))
assert res.OK
events := agent.RecordedEvents()
var foundStart bool
for _, ev := range events {
    if ev.Type == core.EventToolStart {
        assert ev.ParentToolUseID == "call_parent_999"
        foundStart = true
    }
}
assert foundStart
batchRes := executeBatch(ctx, caller, []core.ToolCall{
    {ID: "c1", Name: "read_file", Arguments: `{"path":"a.txt"}`},
    {ID: "c2", Name: "read_file", Arguments: `{"path":"b.txt"}`},
})
assert len(batchRes) == 2

rootMod := parseModFile("go.mod")
assert rootMod.Module.Mod.Path == "github.com/agent-fox-dev/agentkit-go"

csMod := parseModFile("codesearch/go.mod")
assert csMod.Module.Mod.Path == "github.com/agent-fox-dev/agentkit-go/codesearch"
var foundReq, foundReplace bool
for _, req := range csMod.Require {
    if req.Mod.Path == "github.com/agent-fox-dev/agentkit-go" && req.Mod.Version == "v0.0.0" {
        foundReq = true
    }
}
assert foundReq
for _, rep := range csMod.Replace {
    if rep.Old.Path == "github.com/agent-fox-dev/agentkit-go" && rep.New.Path == ".." {
        foundReplace = true
    }
}
assert foundReplace

files := findFiles(".", "*.go")
for _, path := range files {
    content := readFile(path)
    assert !strings.Contains(content, "\"github.com/agentfox/agentkit-go")
}

mod := parseModFile("go.mod")
disallowed := []string{
    "golang.org/x/net",
    "golang.org/x/image",
    "golang.org/x/time",
    "code.dny.dev/ssrf",
}
for _, req := range mod.Require {
    if !req.Indirect {
        for _, dis := range disallowed {
            assert req.Mod.Path != dis
        }
    }
}

cmd := exec.Command("go", "list", "-m", "-f", "{{if not .Indirect}}{{.Path}}{{end}}", "all")
out, err := cmd.Output()
assert err == nil
lines := strings.Split(strings.TrimSpace(string(out)), "\n")
approvedPrefixes := []string{
    "github.com/agent-fox-dev/agentkit-go",
    "github.com/bmatcuk/doublestar/v4",
    "github.com/modelcontextprotocol/go-sdk",
    "github.com/pelletier/go-toml/v2",
    "github.com/tree-sitter/",
    "go.starlark.net",
}
for _, dep := range lines {
    if dep == "" { continue }
    var ok bool
    for _, app := range approvedPrefixes {
        if strings.HasPrefix(dep, app) { ok = true; break }
    }
    assert ok
}
